import SwiftUI

enum SharingVisibilityStudyBank {
    static let sections: [StudySection] = [
        // Permissions to Standard Objects, Custom Objects, and Fields (5 objectives, 45 topics)
        StudySection(
            id: "permissions",
            title: "Permissions to Standard Objects, Custom Objects, and Fields",
            color: Color(red: 0.30, green: 0.50, blue: 0.80),
            lightColor: Color(red: 0.90, green: 0.94, blue: 1.00),
            icon: "lock.shield.fill",
            objectives: [
                StudyObjective(
                    id: "permissions_obj1",
                    title: "Given a scenario, recommend the right level of object permissions needed to provide the appropriate access to a set of users.",
                    topics: [
                        StudyTopic(id: "permissions_obj1_q1", number: 1, question: "How profiles and permission sets work together to grant object permissions.", answer: "Every Salesforce user has exactly one profile, which sets a baseline for object, field, and system permissions. Permission sets are additive layers assigned on top of the profile. Together they define what a user can do at the object level. The profile is required; permission sets are optional and stackable."),
                        StudyTopic(id: "permissions_obj1_q2", number: 2, question: "Why a user's effective object access is always the union (most permissive) of all assigned profiles and permission sets.", answer: "Salesforce evaluates all permissions granted by the profile and every assigned permission set, then applies the most permissive result. If the profile grants Read and a permission set grants Edit, the user gets Edit. There is no way to use a permission set to take away access the profile already grants (except via muting permission sets inside a permission set group)."),
                        StudyTopic(id: "permissions_obj1_q3", number: 3, question: "How permission set groups aggregate multiple permission sets.", answer: "A permission set group (PSG) bundles multiple permission sets into a single assignable unit. Assigning the PSG gives the user the union of all included permission sets. PSGs also support muting permission sets, which subtract specific permissions from within the group without touching the underlying permission sets or the profile."),
                        StudyTopic(id: "permissions_obj1_q4", number: 4, question: "Difference between 'View All' and 'Read' object permissions and when each is the correct choice for a user who should see all records regardless of OWD.", answer: "- Read lets a user see records they own, records shared with them via hierarchy/sharing rules/manual shares, and public records. It respects OWD and sharing.\n\n- View All bypasses OWD and sharing entirely for that object. The user sees every record, period.\n\nUse View All when a user must see all records of an object unconditionally, regardless of ownership or sharing. Use Read when normal sharing rules should govern visibility."),
                        StudyTopic(id: "permissions_obj1_q5", number: 5, question: "'View All Data' and 'Modify All Data' system permissions: what they override and which objects they apply to.", answer: "These are system-level permissions on the profile or permission set. View All Data grants Read + View All across every object in the org. Modify All Data grants full CRUD + View All + Modify All across every object. Both completely bypass OWD, sharing rules, role hierarchy, and field-level security enforcement at the record level. They apply org-wide to all standard and custom objects."),
                        StudyTopic(id: "permissions_obj1_q6", number: 6, question: "Why assigning 'View All Data' or 'Modify All Data' is architecturally equivalent to bypassing all record-level sharing.", answer: "These permissions override every sharing layer: OWD, role hierarchy, sharing rules, manual shares, and Apex sharing. A user with either permission is functionally equivalent to a System Administrator from a data-access standpoint. Assigning them to non-admin users defeats the purpose of any sharing model and is a significant security anti-pattern."),
                        StudyTopic(id: "permissions_obj1_q7", number: 7, question: "How 'Modify All' object permission interacts with record-level sharing rules and OWD settings when a user must manage all records regardless of ownership.", answer: "Modify All is the object-level equivalent of Modify All Data, but scoped to a single object. It grants full CRUD on every record of that object regardless of OWD, sharing rules, or ownership. It is the correct minimum-privilege choice when a user must manage all records of one specific object without granting org-wide override."),
                        StudyTopic(id: "permissions_obj1_q8", number: 8, question: "Which object permission combination (Read, Create, Edit, Delete, View All, Modify All) is appropriate given a business role that needs to update existing records but never delete them?", answer: "Grant Read + Edit (and optionally Create if they create records). Do not grant Delete or Modify All. If they must update records they do not own and OWD is Private, also grant View All to see those records, or rely on sharing rules to open access. Keeping Delete unchecked ensures no record can be destroyed by this role."),
                        StudyTopic(id: "permissions_obj1_q9", number: 9, question: "Which permission set or profile configuration allows a user to create and edit Contacts but not delete them, while still viewing all related Accounts?", answer: "On the Contact object: grant Read, Create, Edit only. Do not grant Delete.\n\nOn the Account object: grant Read (sharing rules or OWD open visibility to related accounts; use View All if they must see all accounts regardless of sharing).\n\nApply these via a permission set assigned on top of a restrictive base profile to maintain least privilege."),
                        StudyTopic(id: "permissions_obj1_q10", number: 10, question: "Selecting the minimum necessary object permissions for a read-only integration user that must access all Opportunity records without opening up record sharing broadly.", answer: "Grant Read + View All on the Opportunity object. View All scopes exclusively to Opportunity, so it does not open any other object. Do not grant Create, Edit, Delete, or any system-level override permission. This satisfies the \"see all Opportunity records\" requirement with the narrowest possible footprint."),
                        StudyTopic(id: "permissions_obj1_q11", number: 11, question: "How muting permission sets within a permission set group can restrict specific permissions that member permission sets would otherwise grant.", answer: "A muting permission set is a special type that can only exist inside a PSG. It explicitly revokes individual permissions that the bundled permission sets would otherwise aggregate. For example, if two included permission sets together grant Delete on Cases, a muting permission set can remove Delete, producing a net result of no Delete for users assigned that PSG. It does not affect the underlying permission sets themselves.")
                    ]
                ),
                StudyObjective(
                    id: "permissions_obj2",
                    title: "Given a scenario, recommend the correct level of field permissions needed to provide the appropriate access to a set of users.",
                    topics: [
                        StudyTopic(id: "permissions_obj2_q1", number: 12, question: "How field-level security (FLS) interacts with page layouts to control field visibility and the authoritative control mechanism when both are configured differently.", answer: "FLS is the authoritative security layer. Page layouts only control UI presentation. If FLS marks a field as hidden, the user cannot see it anywhere, even if the page layout includes it. If FLS marks a field as Read-Only but the page layout marks it as editable, the user sees it but cannot edit it. FLS always wins on access; page layouts cannot grant access that FLS denies."),
                        StudyTopic(id: "permissions_obj2_q2", number: 13, question: "Impact of setting a field to 'Read-Only' in FLS versus removing it from the page layout on API access and programmatic SOQL queries.", answer: "- FLS Read-Only: field is returned in SOQL queries and API responses but cannot be written. Still accessible via API.\n\n- Removed from page layout: field is simply not shown in the UI. It remains fully accessible via SOQL, API, and reports because page layouts have zero impact on API or programmatic access.\n\nFor true security, FLS must be configured, not just page layout removal."),
                        StudyTopic(id: "permissions_obj2_q3", number: 14, question: "Which approach grants field-level read access to a subset of users without modifying the profile shared by all users in that role?", answer: "Use a permission set. Create a permission set that grants Read access to the field, then assign it only to the target users. The shared profile remains unchanged, so other users in the same role are unaffected. This is the standard pattern for field-level exceptions within a role."),
                        StudyTopic(id: "permissions_obj2_q4", number: 15, question: "How to enforce that a sensitive custom field on Case is visible only to support managers using permission sets while keeping the field accessible to automation.", answer: ""),
                        StudyTopic(id: "permissions_obj2_q5", number: 16, question: "Set the field to **Hidden** in the base profile (or all non-manager profiles).", answer: ""),
                        StudyTopic(id: "permissions_obj2_q6", number: 17, question: "Create a permission set with **Read** (or Read-Write) on the field and assign it only to support managers.", answer: ""),
                        StudyTopic(id: "permissions_obj2_q7", number: 18, question: "For automation (flows, triggers, batch jobs): if running in system context (triggers run as system mode), FLS is bypassed by default. If using Flow, use the \"Run in System Context\" option or ensure the running user has the permission set. Apex with `WITH SECURITY_ENFORCED` or `stripInaccessible()` explicitly checks FLS; running without those enforces field access by system mode, so automation remains functional.", answer: ""),
                        StudyTopic(id: "permissions_obj2_q8", number: 19, question: "Given a scenario where a user can see a field on the page layout but not through the API, which FLS configuration is the cause and how to resolve it.", answer: "The field is set to Read-Only or Visible in FLS (so it shows on page layout) but the profile or permission set has the field set to Hidden for API access contexts, OR, more precisely, the field is not accessible via the API because FLS for that profile/permission set is Hidden. Resolution: open the profile or permission set, find Field Permissions for the object, and set the field to at least Read to expose it through the API.")
                    ]
                ),
                StudyObjective(
                    id: "permissions_obj3",
                    title: "Given a scenario, recommend the appropriate mechanism to hide data at the user interface level.",
                    topics: [
                        StudyTopic(id: "permissions_obj3_q1", number: 20, question: "How record types in conjunction with profiles control which picklist values and page layouts a user sees.", answer: "Each profile is mapped to a record type per object. That mapping determines which page layout renders for users of that profile when they view a record of that type, and which picklist values are available to them. Record types allow different subsets of picklist values and different layouts per user population without separate objects."),
                        StudyTopic(id: "permissions_obj3_q2", number: 21, question: "When record types alone are insufficient for access control.", answer: "Record types control layout and picklist values, not field visibility or record access. A user assigned to a different record type can still see records of another type (subject to OWD/sharing). Record types do not hide fields, they do not restrict API access, and they do not prevent users from seeing records of a different type. They must be combined with FLS, OWD, and sharing rules for real security."),
                        StudyTopic(id: "permissions_obj3_q3", number: 22, question: "Choosing between page layout removal, FLS hidden, and record type restrictions to hide a set of fields from a specific user population in the UI.", answer: "| Mechanism | Hides in UI | Hides from API | Scope |\n\n|---|---|---|---|\n\n| Page layout removal | Yes | No | Layout-specific |\n\n| FLS hidden | Yes | Yes | Profile/Permission set |\n\n| Record type restriction | Picklists/layout only | No | Record type per profile |\n\nBest choice for true field hiding: FLS set to Hidden on the profile or permission set. Use page layout removal as a UI polish layer only, not a security control."),
                        StudyTopic(id: "permissions_obj3_q4", number: 23, question: "Limitations of hiding data only at the UI layer when the data is still accessible via SOQL, API, or reports — and the recommended architectural fix.", answer: "Page layout removal and record type controls are presentation-only. A user or integration with API access can still query hidden fields via SOQL or REST/SOAP. Reports also bypass page layout restrictions. The architectural fix is to set FLS to Hidden at the profile/permission set level. For truly sensitive data (PII, PCI), layer Shield Platform Encryption so that even users with DB-level access cannot read plaintext values.")
                    ]
                ),
                StudyObjective(
                    id: "permissions_obj4",
                    title: "Given a scenario, determine the appropriate access controls to protect sensitive data (e.g. PCI, PII, or HIPAA).",
                    topics: [
                        StudyTopic(id: "permissions_obj4_q1", number: 24, question: "How Salesforce Shield Platform Encryption differs from Classic Encryption.", answer: "| | Classic Encryption | Shield Platform Encryption |\n\n|---|---|---|\n\n| Encryption type | 128-bit AES, custom field type only | 256-bit AES, standard and custom fields |\n\n| Searchable | No | Yes (deterministic encryption) |\n\n| Works with SOQL | Limited | Broader support |\n\n| Key management | Salesforce-managed | Tenant-managed (BYOK available) |\n\n| Compliance grade | Basic masking | HIPAA, PCI, GDPR-grade |\n\nShield is the enterprise-grade solution. Classic Encryption is a legacy, limited option not suitable for regulated data."),
                        StudyTopic(id: "permissions_obj4_q2", number: 25, question: "Which encryption (Shield vs Classic) should be used to satisfy HIPAA requirements for a health data field.", answer: "Shield Platform Encryption. HIPAA requires encryption of PHI at rest with proper key management. Classic Encryption does not meet this bar. Shield encrypts data at the database layer, supports tenant-managed keys (BYOK), and provides the audit trails required for HIPAA compliance."),
                        StudyTopic(id: "permissions_obj4_q3", number: 26, question: "Which combination of Platform Encryption, FLS, and object permissions is appropriate to protect PII fields from being viewed by support agents while allowing billing users access?", answer: ""),
                        StudyTopic(id: "permissions_obj4_q4", number: 27, question: "**Shield Platform Encryption** on the PII fields (encrypts at rest).", answer: ""),
                        StudyTopic(id: "permissions_obj4_q5", number: 28, question: "**FLS Hidden** on the support agent profile for those fields (prevents UI and API access).", answer: ""),
                        StudyTopic(id: "permissions_obj4_q6", number: 29, question: "**FLS Read** (or Read-Write) granted to billing users via a permission set.", answer: ""),
                        StudyTopic(id: "permissions_obj4_q7", number: 30, question: "**Object Read** permission for both roles so they can access the object, just not the sensitive fields for agents.", answer: "This ensures agents see the record but not the PII, while billing users see everything, and the data is encrypted at rest regardless of who queries it."),
                        StudyTopic(id: "permissions_obj4_q8", number: 31, question: "Given PCI compliance requirements, which access control mechanisms must be layered to prevent unauthorized users from viewing cardholder data fields in Salesforce?", answer: "- Shield Platform Encryption on cardholder data fields (encryption at rest with tenant-managed keys).\n\n- FLS Hidden on all profiles except those with explicit PCI-scoped permission sets.\n\n- Restrict API access via connected app policies and IP restrictions for integration users.\n\n- Event Monitoring to log field access and report exports.\n\n- Transaction Security Policies to alert or block suspicious access patterns.\n\n- Audit Trail to maintain a log of configuration changes.\n\nNo single mechanism is sufficient; PCI requires defense in depth."),
                        StudyTopic(id: "permissions_obj4_q9", number: 32, question: "Audit trail and event monitoring capabilities in Salesforce used to detect and report on unauthorized access attempts to sensitive data.", answer: "- Setup Audit Trail: logs all configuration changes (who changed what and when) for up to 180 days.\n\n- Event Monitoring (Shield or add-on): provides granular logs for Login, Report Export, API calls, ListViews, record access, and more. Each event is a log file queryable via the EventLogFile object.\n\n- Transaction Security: real-time policies that can block or alert on specific actions (e.g., exporting more than N records).\n\n- Field Audit Trail: tracks field-level change history beyond the standard 18-month limit (requires Shield)."),
                        StudyTopic(id: "permissions_obj4_q10", number: 33, question: "When should an architect recommend data masking via a custom solution versus native Salesforce field encryption for protecting PII in a multi-cloud integration?", answer: "Use native Shield encryption when data lives primarily in Salesforce and integrations can tolerate encrypted payloads or use Salesforce APIs. Choose custom data masking when:\n\n- Data must flow to external systems that cannot decrypt Shield-encrypted values.\n\n- Integration middleware or data warehouses require plaintext with controlled unmasking at the edge.\n\n- Tokenization is needed (replace value with a non-reversible token that maps to the real value in a secure vault).\n\nIn multi-cloud scenarios, a tokenization or masking layer at the integration tier is often required alongside (not instead of) Shield encryption within Salesforce.")
                    ]
                ),
                StudyObjective(
                    id: "permissions_obj5",
                    title: "Given a scenario, recommend the appropriate programmatic solution to ensure security settings are enforced.",
                    topics: [
                        StudyTopic(id: "permissions_obj5_q1", number: 34, question: "Difference between 'with sharing', 'without sharing', and 'inherited sharing' in Apex and when each keyword is correct for a class that processes sensitive Contact records.", answer: "- `with sharing`: enforces the running user's record-level sharing rules. The user only sees records they have access to. Use this for classes invoked in user context where sharing should be respected (most business logic classes).\n\n- `without sharing`: ignores sharing rules entirely; runs in system mode for record access. Use sparingly, only when the business logic genuinely requires access to all records (e.g., internal recalculation jobs).\n\n- `inherited sharing`: inherits the sharing context of the calling class. Use for utility or service classes that should adapt to whatever context calls them.\n\nFor sensitive Contact processing in user context: use `with sharing`."),
                        StudyTopic(id: "permissions_obj5_q2", number: 35, question: "How SOQL in an Apex trigger enforces (or bypasses) record-level sharing depending on the class-level sharing declaration.", answer: "Triggers themselves run in system context by default (no sharing keyword means no sharing enforcement). If the trigger handler class is declared `with sharing`, SOQL inside it respects the running user's sharing. If declared `without sharing` or no keyword, SOQL returns all records regardless of sharing. The sharing keyword on the class containing the SOQL is what matters, not the trigger file itself."),
                        StudyTopic(id: "permissions_obj5_q3", number: 36, question: "The correct approach when an Apex trigger must respect row visibility for non-admin users.", answer: "Delegate logic to a handler class explicitly declared `with sharing`. The trigger fires in system context, but as soon as it calls a `with sharing` class, subsequent SOQL in that class respects the running user's record access. This is the handler pattern: trigger invokes `MyObjectTriggerHandler` (declared `with sharing`), which queries and processes records within the user's sharing context."),
                        StudyTopic(id: "permissions_obj5_q4", number: 37, question: "How WITH SECURITY_ENFORCED or stripInaccessible() in Apex enforces FLS and object-level permissions for programmatically queried data.", answer: "- `WITH SECURITY_ENFORCED` (inline SOQL clause): throws an exception if the running user lacks FLS or object Read access for any field or object in the query. It's a hard stop, so handle the exception gracefully.\n\n- `Security.stripInaccessible()`: strips fields or records from a query result (or SObject list) that the user cannot access, instead of throwing an exception. More flexible for partial-access scenarios.\n\nBoth enforce FLS in Apex code that would otherwise bypass it due to system context."),
                        StudyTopic(id: "permissions_obj5_q5", number: 38, question: "How the Security.stripInaccessible() method behaves when applied before DML operations to prevent unauthorized field writes.", answer: "Call `Security.stripInaccessible(AccessType.CREATABLE, records)` before insert, or `AccessType.UPDATABLE` before update. The method returns a `SObjectAccessDecision` object. Access `.getRecords()` on it to get a sanitized list with inaccessible fields removed. Performing DML on this sanitized list prevents unauthorized field writes even if the original data included values for fields the user cannot edit."),
                        StudyTopic(id: "permissions_obj5_q6", number: 39, question: "A developer's Apex class runs in system mode and bypasses FLS. Which code-level changes enforce field security without breaking existing functionality?", answer: ""),
                        StudyTopic(id: "permissions_obj5_q7", number: 40, question: "Add `with sharing` to the class (enforces record sharing, not FLS by itself).", answer: ""),
                        StudyTopic(id: "permissions_obj5_q8", number: 41, question: "Add `WITH SECURITY_ENFORCED` to SOQL statements to enforce FLS on queries.", answer: ""),
                        StudyTopic(id: "permissions_obj5_q9", number: 42, question: "Wrap SObject lists in `Security.stripInaccessible()` before processing or DML to remove inaccessible fields.", answer: ""),
                        StudyTopic(id: "permissions_obj5_q10", number: 43, question: "Use `DescribeFieldResult.isAccessible()` / `isCreateable()` / `isUpdateable()` for manual per-field checks if fine-grained control is needed.", answer: "Test thoroughly: if existing logic depends on fields being present that some users cannot access, `stripInaccessible()` is safer than `WITH SECURITY_ENFORCED` because it degrades gracefully rather than throwing."),
                        StudyTopic(id: "permissions_obj5_q11", number: 44, question: "How Visualforce and Lightning Web Components differ in enforcing FLS automatically, and what developers must do to avoid FLS bypass in each.", answer: "- Visualforce: does NOT automatically enforce FLS. Fields rendered via `<apex:outputField>` do respect FLS, but raw `{!record.FieldName}` expressions in custom markup do not. Developers must explicitly check FLS in the controller or use `<apex:outputField>`.\n\n- LWC (and Aura): also does NOT automatically enforce FLS on data returned by Apex methods. Wire adapters using `getRecord` (UI API) DO enforce FLS. For Apex-backed LWCs, the Apex method must enforce FLS via `stripInaccessible()` or `WITH SECURITY_ENFORCED`.\n\nBottom line: use UI API wire adapters where possible; otherwise, enforce FLS explicitly in the Apex layer."),
                        StudyTopic(id: "permissions_obj5_q12", number: 45, question: "When a batch Apex job must access all records regardless of sharing but must still respect FLS, which class-level sharing keyword and SOQL approach is appropriate?", answer: "Declare the batch class `without sharing` to bypass record-level sharing (so all records are accessible). Then enforce FLS by using `Security.stripInaccessible(AccessType.READABLE, results)` on the query results before processing, or add `WITH SECURITY_ENFORCED` to the SOQL. This combination lets the batch see all records while still honoring field-level visibility rules.")
                    ]
                )
            ]
        ),

        // Access to Records (9 objectives, 93 topics)
        StudySection(
            id: "record_access",
            title: "Access to Records",
            color: Color(red: 0.20, green: 0.60, blue: 0.50),
            lightColor: Color(red: 0.88, green: 0.96, blue: 0.94),
            icon: "doc.text.fill",
            objectives: [
                StudyObjective(
                    id: "record_access_obj1",
                    title: "Given a set of conditions, recommend the appropriate organization-wide defaults to restrict access to records.",
                    topics: [
                        StudyTopic(id: "record_access_obj1_q1", number: 46, question: "How OWD settings for a given object establish the baseline record access and why setting OWD to 'Public Read/Write' makes all sharing rules redundant.", answer: "OWD is the floor of record access. It defines the minimum access every user has to every record they do not own. When OWD is set to Public Read/Write, every user already has full read and write access to all records by default. Sharing rules, sharing groups, and role hierarchy only add access on top of OWD. Since Public Read/Write is already the maximum additive access, no sharing rule can provide anything additional, making them all redundant."),
                        StudyTopic(id: "record_access_obj1_q2", number: 47, question: "When is 'Private' OWD appropriate versus 'Public Read Only', given a business requirement where managers should see all subordinate records but reps should only see their own?", answer: "Use Private. With Private OWD, users only see records they own by default. Managers see subordinate records via the role hierarchy (because \"Grant Access Using Hierarchies\" is enabled by default). Reps only see their own records. Public Read Only would let every rep see every other rep's records, violating the requirement."),
                        StudyTopic(id: "record_access_obj1_q3", number: 48, question: "The 'Controlled by Parent' OWD setting for a custom object and how it governs record access relative to the Lookup or Master-Detail parent relationship.", answer: "When OWD is Controlled by Parent, the child record's access is entirely determined by the parent record's access. If a user can see the parent, they see the child. If they cannot see the parent, they cannot see the child. This setting is mandatory for Master-Detail children and optional for Lookup children. It cannot be used if the child has no lookup/master-detail relationship or if the object has multiple parent relationships."),
                        StudyTopic(id: "record_access_obj1_q4", number: 49, question: "How OWD for a child object relates to OWD for the parent in a Master-Detail relationship and what access a user gains to child records through the parent.", answer: "In a Master-Detail relationship, the child's OWD is automatically set to Controlled by Parent and cannot be changed. Access flows from parent to child: a user who can read the parent can read the child, a user who can edit the parent can edit the child (subject to child object CRUD permissions). The child has no independent sharing model."),
                        StudyTopic(id: "record_access_obj1_q5", number: 50, question: "How external OWD settings differ from internal OWD settings and why they can be set independently for each object.", answer: "Salesforce allows a separate OWD for external users (portal/Experience Cloud users) that can be equal to or more restrictive than the internal OWD. This lets orgs maintain open internal sharing (e.g., Public Read Only internally) while locking down external access (e.g., Private externally). They are set independently because internal users and external users have fundamentally different trust levels and access requirements."),
                        StudyTopic(id: "record_access_obj1_q6", number: 51, question: "When setting a lower external OWD is architecturally required.", answer: "When the org has Experience Cloud (Community) users, Guest users, or portal users who should not have the same default access as internal users. If internal OWD is Public Read Only but portal users should only see records they own (or are explicitly shared to them), external OWD must be set to Private. Without a lower external OWD, portal users inherit the internal default."),
                        StudyTopic(id: "record_access_obj1_q7", number: 52, question: "A company has internal OWD of Public Read Only for Accounts but needs portal users to see only their own account data. Which external OWD setting achieves this without additional sharing rules?", answer: "Set the external OWD for Account to Private. Portal users then only see Account records they own or that are explicitly shared with them, while internal users continue to see all Accounts under the Public Read Only baseline."),
                        StudyTopic(id: "record_access_obj1_q8", number: 53, question: "Which combination of OWD settings for Accounts and Contacts ensures that portal users can only see Contacts directly associated with their Account?", answer: "- Account external OWD: Private (portal users see only their account).\n\n- Contact OWD: Controlled by Parent (Contact access is determined by Account access).\n\nWith these settings, a portal user who has access to their Account automatically sees Contacts on that Account, and no others."),
                        StudyTopic(id: "record_access_obj1_q9", number: 54, question: "Given a regulated healthcare org, which OWD baseline for Patient records minimizes exposure while allowing controlled sharing via exception rules?", answer: "Set OWD to Private. This ensures no user sees any Patient record by default unless they own it or access is explicitly granted via role hierarchy, sharing rules, teams, or Apex sharing. Private OWD is the principle of least privilege baseline; all sharing is additive and auditable.")
                    ]
                ),
                StudyObjective(
                    id: "record_access_obj2",
                    title: "Given a set of conditions, recommend a solution that leverages the role hierarchy to support the record access requirements.",
                    topics: [
                        StudyTopic(id: "record_access_obj2_q1", number: 55, question: "How the role hierarchy grants implicit record access upward and the conditions under which a manager does NOT automatically inherit access to a subordinate's record.", answer: "Users at higher roles in the hierarchy automatically inherit Read (and sometimes Edit) access to records owned by subordinates below them. A manager does NOT inherit access when:\n\n- \"Grant Access Using Hierarchies\" is disabled for that object.\n\n- The record is owned by a user outside the manager's branch of the hierarchy.\n\n- The child object's OWD is Controlled by Parent with its own access rules."),
                        StudyTopic(id: "record_access_obj2_q2", number: 56, question: "How 'Grant Access Using Hierarchies' checkbox for an object affects whether role hierarchy-based access applies.", answer: "This checkbox (visible in OWD settings) controls whether role hierarchy sharing is enabled for a given object. When unchecked, managers do not automatically see subordinates' records, no matter where they sit in the hierarchy. It can be disabled for custom objects. It is always enabled for standard objects and cannot be turned off for them."),
                        StudyTopic(id: "record_access_obj2_q3", number: 57, question: "A sales manager needs to see all Opportunities owned by their direct and indirect reports. Which role hierarchy configuration achieves this without sharing rules?", answer: "Place the manager's role above all rep roles in the hierarchy. Ensure \"Grant Access Using Hierarchies\" is enabled on the Opportunity object (it is by default for standard objects). The manager will then see all Opportunity records owned by anyone in a role below theirs in that branch. No sharing rules are needed."),
                        StudyTopic(id: "record_access_obj2_q4", number: 58, question: "How position in the role hierarchy determines which sharing rule targets (Roles, Roles and Subordinates) grant access to a given user when a sharing rule is evaluated.", answer: "- Roles: the sharing rule applies only to users directly in that named role.\n\n- Roles and Subordinates: the sharing rule applies to users in that role AND all roles below it in the hierarchy.\n\nA user gains access from a sharing rule if they are in the target role or any subordinate role (when \"Roles and Subordinates\" is used). Their position in the hierarchy determines which \"Roles and Subordinates\" targets include them."),
                        StudyTopic(id: "record_access_obj2_q5", number: 59, question: "When an architect should choose a flat role hierarchy over a deep role hierarchy.", answer: "Prefer a flat hierarchy when:\n\n- The org has few management layers.\n\n- Broad record visibility is needed across many users.\n\n- Sharing recalculation performance is a concern (fewer levels = less computation).\n\n- Permission sets and sharing rules handle exceptions more cleanly than role depth.\n\nFlat hierarchies are simpler to maintain and recalculate faster at scale."),
                        StudyTopic(id: "record_access_obj2_q6", number: 60, question: "Scalability implications of flat versus deep role hierarchies.", answer: "- Flat: faster sharing recalculation, simpler administration. Risk: may require more sharing rules to compensate for missing hierarchy-based access.\n\n- Deep: more granular access control via hierarchy alone. Risk: exponential growth in sharing rows during recalculation, potential timeouts in very large orgs, increased complexity for administrators.\n\nIn orgs with millions of records, a deep hierarchy can cause severe sharing recalculation performance issues."),
                        StudyTopic(id: "record_access_obj2_q7", number: 61, question: "An org has a matrix structure where users report to multiple managers. Which Salesforce mechanism compensates for the single-parent role hierarchy limitation?", answer: "Salesforce roles are single-parent (each role has one parent). For matrix reporting, use:\n\n- Manual sharing for one-off cross-manager access.\n\n- Public groups that include both managers as members, targeted by a sharing rule.\n\n- Account Teams / Opportunity Teams so owners can explicitly share with additional managers.\n\n- Criteria-based sharing rules that target a group including all relevant managers.\n\nThere is no native matrix hierarchy; these mechanisms combine to approximate it."),
                        StudyTopic(id: "record_access_obj2_q8", number: 62, question: "When turning off 'Grant Access Using Hierarchies' for an object is appropriate.", answer: "Turn it off when the business requirement explicitly states that managers should NOT automatically see their subordinates' records for a custom object. Common use cases: HR-related records (salary, performance), personal journals, private notes. This forces all sharing to be explicit rather than implicit via hierarchy, supporting strict data confidentiality requirements.")
                    ]
                ),
                StudyObjective(
                    id: "record_access_obj3",
                    title: "Given a set of conditions, determine how sharing rules can be implemented to support the record access requirements.",
                    topics: [
                        StudyTopic(id: "record_access_obj3_q1", number: 63, question: "Difference between criteria-based sharing rules and ownership-based sharing rules, and when each is the correct choice for a specific access pattern.", answer: "- Ownership-based: shares records based on who owns them. \"Share all records owned by Role X with Role Y.\" Best when the ownership pattern aligns with the sharing need (e.g., all sales reps' records visible to support).\n\n- Criteria-based: shares records based on field values on the record itself, regardless of ownership. \"Share all Cases where Status = Escalated with the Escalation Team.\" Best when access depends on record attributes, not owner identity."),
                        StudyTopic(id: "record_access_obj3_q2", number: 64, question: "Sharing rules can only open access beyond OWD, never restrict it. What are the implications when a sharing rule grants broader access than intended?", answer: "Once created, a sharing rule only adds access. You cannot use a sharing rule to take access away. If a rule grants broader access than intended, the only remedies are:\n\n- Delete or narrow the sharing rule.\n\n- Change the OWD to be more restrictive (which triggers full recalculation).\n\n- Use more specific criteria or target groups to limit who gets the rule's access.\n\nThis is why starting with the most restrictive OWD and opening up carefully is the recommended approach."),
                        StudyTopic(id: "record_access_obj3_q3", number: 65, question: "When sharing rules reference public groups versus roles or role-and-subordinates, and which target provides better long-term maintainability for a dynamic org.", answer: "Public groups are more maintainable for dynamic orgs. Adding or removing a user from a public group automatically updates sharing without touching the sharing rule itself. Role-based targets require role reassignment when org structure changes. Use roles when sharing aligns cleanly with the org chart. Use public groups when the sharing audience crosses roles or changes frequently."),
                        StudyTopic(id: "record_access_obj3_q4", number: 66, question: "A business unit requires that all Cases with a specific record type be visible to a separate support tier group. Which sharing rule type and configuration achieves this?", answer: "Use a criteria-based sharing rule on the Case object:\n\n- Criteria: Record Type = [Target Record Type].\n\n- Share with: the public group or role representing the support tier.\n\n- Access level: Read Only or Read/Write as required.\n\nThis fires automatically whenever a Case's record type matches, regardless of who owns it."),
                        StudyTopic(id: "record_access_obj3_q5", number: 67, question: "How queues can be used as a sharing rule target to grant record access to all members of a queue.", answer: "Queues can be selected as the target in an ownership-based sharing rule. This grants all current queue members the specified access level to records owned by the source (role, group, etc.). Queue membership is dynamic, so as users join or leave the queue, their access updates accordingly."),
                        StudyTopic(id: "record_access_obj3_q6", number: 68, question: "Difference between queue membership-based access and role-based sharing rule access.", answer: "- Queue-based access: tied to queue membership. User joins queue, gets access; leaves queue, loses access. Flexible for dynamic team assignments.\n\n- Role-based access: tied to role assignment in the hierarchy. More stable but less flexible. Changing a user's role can inadvertently alter their sharing access across many rules."),
                        StudyTopic(id: "record_access_obj3_q7", number: 69, question: "A service team uses a queue to manage unassigned Cases. Which sharing configuration ensures that all queue members can edit any Case in the queue while non-members cannot see the records?", answer: ""),
                        StudyTopic(id: "record_access_obj3_q8", number: 70, question: "Set Case OWD to **Private**.", answer: ""),
                        StudyTopic(id: "record_access_obj3_q9", number: 71, question: "Create an **ownership-based sharing rule**: \"Cases owned by [Queue]\" shared with \"[Queue]\" at **Read/Write** access.", answer: "When a Case is assigned to the queue, queue members get Read/Write. Non-members have no access (Private OWD baseline). When a Case is reassigned to an individual owner, the queue-based sharing no longer applies."),
                        StudyTopic(id: "record_access_obj3_q10", number: 72, question: "How criteria-based sharing rules recalculate when a record's field value changes, and which scenarios may result in stale sharing or delayed access.", answer: "When a field used in criteria-based sharing changes, Salesforce asynchronously recalculates sharing for that record. During bulk operations or high-volume updates, this recalculation is queued and may be delayed. During the delay window, a user who should gain access (or lose access) based on the new field value may see stale results. This is a known architectural risk for time-sensitive security requirements."),
                        StudyTopic(id: "record_access_obj3_q11", number: 73, question: "Maximum number of sharing rules per object (300 owner-based + 300 criteria-based).", answer: "Salesforce enforces a limit of 300 ownership-based and 300 criteria-based sharing rules per object, for a total of 600 per object. This is a hard platform limit and cannot be increased."),
                        StudyTopic(id: "record_access_obj3_q12", number: 74, question: "Implications when the sharing rule limit is approached in a large org with complex access patterns.", answer: "When approaching the limit:\n\n- Consolidate rules by merging similar criteria using OR logic on picklist values.\n\n- Replace multiple role-based rules with public group-based rules (one rule per group instead of per role).\n\n- Refactor to Apex managed sharing for the most complex patterns.\n\n- Revisit OWD: if a less restrictive OWD reduces the need for rules, that may be the better architectural choice.\n\nHitting the limit is a signal that the sharing model may be over-engineered at the declarative layer.")
                    ]
                ),
                StudyObjective(
                    id: "record_access_obj4",
                    title: "Given a set of conditions, determine how groups can support the record access requirements.",
                    topics: [
                        StudyTopic(id: "record_access_obj4_q1", number: 75, question: "Difference between public groups, personal groups, and role-based groups.", answer: "- Public groups: created by admins, available org-wide as sharing targets. Can include users, roles, subordinates, other groups, and portal users.\n\n- Personal groups: created by individual users for their own manual sharing use. Not available as sharing rule targets.\n\n- Role-based groups: Salesforce automatically creates groups for each role and role+subordinates combination. These appear as selectable targets in sharing rules and are system-managed."),
                        StudyTopic(id: "record_access_obj4_q2", number: 76, question: "Which group type is correct for sharing records with a cross-functional team that spans multiple roles.", answer: "Use a public group. Add all relevant users (or roles) from the different teams to the group. Then use a sharing rule targeting that public group. This cleanly handles cross-role membership without restructuring the role hierarchy."),
                        StudyTopic(id: "record_access_obj4_q3", number: 77, question: "How queues differ from public groups in terms of record ownership, member types, and the objects they can be associated with.", answer: "| | Public Group | Queue |\n\n|---|---|---|\n\n| Record ownership | Cannot own records | Can own records |\n\n| Member types | Users, roles, groups, portal users | Users, roles, groups |\n\n| Object association | Any (sharing target) | Specific objects configured per queue |\n\n| Use case | Sharing target | Work item routing + ownership |\n\nQueues are designed for work routing; public groups are designed for sharing."),
                        StudyTopic(id: "record_access_obj4_q4", number: 78, question: "When a queue is the correct mechanism over a public group.", answer: "Use a queue when:\n\n- Records need to be owned by a team (not an individual).\n\n- Work must be routed and assigned to the first available member.\n\n- The object supports queues (Cases, Leads, Orders, custom objects, etc.).\n\nUse a public group when you just need a sharing target without record ownership."),
                        StudyTopic(id: "record_access_obj4_q5", number: 79, question: "How public groups interact with the role hierarchy when a group includes 'Roles and Subordinates' as a member and what access that grants at scale.", answer: "When a public group includes \"Roles and Subordinates,\" every user in that role and all roles below it in the hierarchy is effectively a member. If a sharing rule targets this group, every user in that large role branch gains access. At scale, this can produce a very large number of sharing rows and slow recalculation. Audit group membership before using \"Roles and Subordinates\" in sharing-rule-targeted public groups in large orgs."),
                        StudyTopic(id: "record_access_obj4_q6", number: 80, question: "A company wants to grant a temporary cross-regional team access to a set of Account records. Which group type and sharing mechanism is most maintainable and scalable?", answer: "Create a public group for the temporary team. Add the relevant users. Create a criteria-based or ownership-based sharing rule targeting the public group. When the team dissolves, remove users from the group (or delete it). This approach requires no changes to the sharing rule itself, making it maintainable. It is also scalable because group membership changes are incremental updates."),
                        StudyTopic(id: "record_access_obj4_q7", number: 81, question: "How nesting public groups affects sharing rule evaluation and performance, and when deeply nested groups become an architectural risk.", answer: "Salesforce supports nesting groups (a group can include other groups as members). During sharing evaluation, Salesforce must recursively resolve all nested memberships. Deeply nested groups (many levels deep, or groups containing very large role branches) significantly slow sharing recalculation. The architectural risk threshold is typically 3+ levels of nesting combined with high record volume. Flatten group structures when recalculation timeouts are observed.")
                    ]
                ),
                StudyObjective(
                    id: "record_access_obj5",
                    title: "Given a set of conditions, determine how teams can support the record access requirements.",
                    topics: [
                        StudyTopic(id: "record_access_obj5_q1", number: 82, question: "How Account Teams and Opportunity Teams grant record-level access.", answer: "Team members are added to a specific record, and each member is assigned an access level (Read Only, Read/Write, or Owner). This access is stored as a sharing record on the related Share object. Account Team members can also optionally get access to related Opportunities, Cases, and Contacts on that Account, based on the team access level configured."),
                        StudyTopic(id: "record_access_obj5_q2", number: 83, question: "When Account Teams and Opportunity Teams are the correct mechanism versus sharing rules for dynamic, owner-controlled sharing.", answer: "Use teams when:\n\n- The sharing audience varies record by record (each Account has a different team composition).\n\n- Record owners should control who has access to their specific records.\n\n- You need named individual access rather than role or group-based access.\n\nUse sharing rules when the access pattern is consistent across many records and doesn't need owner-level customization."),
                        StudyTopic(id: "record_access_obj5_q3", number: 84, question: "Limitations of Account Teams and Opportunity Teams — what they cannot do (e.g., grant access to related objects) and when a different mechanism is required.", answer: "- Account Teams grant access to the Account and optionally related Contacts, Opportunities, and Cases, but not to arbitrary custom child objects.\n\n- Opportunity Teams grant access only to the Opportunity itself, not to related objects.\n\n- Team access cannot be used as a sharing rule target.\n\n- If access to custom child objects is needed, use sharing rules or Apex sharing in addition to teams."),
                        StudyTopic(id: "record_access_obj5_q4", number: 85, question: "How Case Teams differ from Account Teams in terms of configuration and access inheritance.", answer: "- Account Teams: role-based team roles configured org-wide; members can get access to multiple related objects.\n\n- Case Teams: configured with predefined team roles, each with a specified access level. Case Teams do NOT provide access to any other objects related to the Case. Access is scoped purely to the Case record.\n\nCase Teams are simpler and more narrowly scoped than Account Teams."),
                        StudyTopic(id: "record_access_obj5_q5", number: 86, question: "When Case Teams are the appropriate solution versus Account Teams.", answer: "Use Case Teams when:\n\n- A cross-functional group needs to collaborate on a specific support case.\n\n- Access should be limited to that Case only, with no spillover to Accounts or other objects.\n\nUse Account Teams when the collaboration extends beyond a single record to the Account and its related records."),
                        StudyTopic(id: "record_access_obj5_q6", number: 87, question: "How default Account Team and Opportunity Team templates work and which sharing access levels they support.", answer: "Users can configure a default team in their personal settings. When they create an Account or Opportunity, their default team is automatically added. Templates define the team members and their access levels. Supported access levels are Read Only and Read/Write for team members (the owner always has full access). Admins can also configure org-level default Account Team templates."),
                        StudyTopic(id: "record_access_obj5_q7", number: 88, question: "When a sales rep adds a colleague to an Opportunity Team with 'Read Only' access but the colleague still needs to edit the Opportunity, which additional configuration is required?", answer: "The team member's access must be changed from Read Only to Read/Write at the team level. Alternatively, if object permissions allow, grant the colleague Edit on the Opportunity object via their profile or permission set (object permissions still govern whether Edit is possible even if team access says Read/Write). Team access levels are a ceiling, not a floor."),
                        StudyTopic(id: "record_access_obj5_q8", number: 89, question: "Behavior when a team member is removed from an Account Team or Opportunity Team.", answer: "When a user is removed from a team, their team-based sharing record is deleted. If no other sharing mechanism (hierarchy, OWD, sharing rules, manual share) grants access, they immediately lose visibility to the record. This is immediate and automatic.")
                    ]
                ),
                StudyObjective(
                    id: "record_access_obj6",
                    title: "Given a set of conditions, determine the correct object relationships that support record access sharing requirements.",
                    topics: [
                        StudyTopic(id: "record_access_obj6_q1", number: 90, question: "How a Master-Detail relationship automatically shares child record access with users who have parent record access, and how this differs from a Lookup relationship.", answer: "In a Master-Detail relationship, child records inherit the parent's sharing. A user with access to the parent automatically gets access to all child records. The child's OWD is forced to \"Controlled by Parent\" with no separate sharing model.\n\nIn a Lookup relationship, the child has its own independent OWD and sharing model. Access to the parent does NOT automatically grant access to child records."),
                        StudyTopic(id: "record_access_obj6_q2", number: 91, question: "When a Lookup relationship is used instead of Master-Detail, what additional sharing configuration is required to ensure child records are visible to users who can see the parent?", answer: "Configure a criteria-based sharing rule or Apex managed sharing on the child object to grant access to users who have parent access. Alternatively, set the child's OWD to Public Read Only if broad visibility is acceptable. There is no automatic inheritance with Lookup, so explicit sharing configuration is always required."),
                        StudyTopic(id: "record_access_obj6_q3", number: 92, question: "An architect must ensure that child Service Appointment records are only visible to users who can see the parent Work Order. Which relationship type enforces this automatically?", answer: "Use a Master-Detail relationship between Work Order (parent) and Service Appointment (child). With the child's OWD set to Controlled by Parent, child visibility is entirely determined by parent access. No additional sharing configuration is needed."),
                        StudyTopic(id: "record_access_obj6_q4", number: 93, question: "How Many-to-Many relationships via junction objects affect record visibility.", answer: "A junction object in a many-to-many relationship has two Master-Detail relationships (or two Lookups). If both are Master-Detail, the junction record's sharing is Controlled by Parent, and Salesforce allows access if the user has access to EITHER parent (not necessarily both). If Lookup relationships are used, the junction has its own independent OWD and requires separate sharing configuration."),
                        StudyTopic(id: "record_access_obj6_q5", number: 94, question: "Which OWD and relationship type combination ensures both parent owners can access a junction record in a Many-to-Many relationship.", answer: "Use Master-Detail for both relationships on the junction object. Salesforce's implicit sharing for junction objects allows access if the user has access to either parent. Both parent owners therefore get access to the junction record automatically. Alternatively, set the junction OWD to Public Read Only, but that opens access to all users, not just the two parent owners."),
                        StudyTopic(id: "record_access_obj6_q6", number: 95, question: "How implicit sharing for portal users on Accounts and Contacts works: a portal user with access to an Account automatically gains access to Contacts associated with that Account through the implicit sharing mechanism.", answer: "Salesforce provides implicit sharing for portal users on the Account-Contact relationship. A portal user who is a contact on an Account gains read access to all other Contacts on that same Account, even without an explicit sharing rule. This is a built-in platform behavior designed for B2B community scenarios. It cannot be configured off; architects must be aware of it to avoid unintended exposure.")
                    ]
                ),
                StudyObjective(
                    id: "record_access_obj7",
                    title: "Given a set of conditions, determine how programmatic sharing supports the record access requirements.",
                    topics: [
                        StudyTopic(id: "record_access_obj7_q1", number: 96, question: "How Apex managed sharing works using the Share object (e.g., AccountShare, OpportunityShare) and which fields are required when inserting a share record programmatically.", answer: "Each standard and custom object with a Private or Public Read Only OWD has a corresponding Share object (e.g., `AccountShare`, `MyObject__Share`). To insert a share record programmatically, the required fields are:\n\n- `ParentId` (or object-specific field like `AccountId`): the record to share.\n\n- `UserOrGroupId`: the user or group receiving access.\n\n- `AccessLevel`: Read or Edit (Write).\n\n- `RowCause`: the sharing reason (use a custom reason for Apex-managed shares)."),
                        StudyTopic(id: "record_access_obj7_q2", number: 97, question: "What a custom Apex sharing reason (row cause) is and how to create one.", answer: "A custom sharing reason identifies Apex-managed share records distinctly from system-managed ones. Create it by adding a Sharing Reason on the custom object's detail page in Setup (or via metadata API). It appears as a picklist value for `RowCause` on the Share object. For standard objects, only the `Manual` row cause is available for programmatic use; custom reasons are for custom objects only."),
                        StudyTopic(id: "record_access_obj7_q3", number: 98, question: "Why a custom row cause is required to prevent Apex-managed share records from being deleted when the record owner changes.", answer: "Share records with `RowCause = Manual` are automatically deleted when the record's owner changes (Salesforce recalculates manual shares on ownership transfer). Share records with a custom row cause are NOT deleted on ownership change. They persist until explicitly deleted by Apex code. This is critical for Apex sharing scenarios where access should survive reassignment."),
                        StudyTopic(id: "record_access_obj7_q4", number: 99, question: "How Apex managed sharing records are affected when the sharing reason is not specified, and the implications for recalculation when the record owner changes.", answer: "If no custom row cause is used (defaulting to Manual or Owner), those share records are deleted when the record owner changes. This means the Apex sharing logic must re-run after every ownership transfer to re-establish access, creating maintenance complexity and potential gaps in access during the window before re-execution."),
                        StudyTopic(id: "record_access_obj7_q5", number: 100, question: "How 'without sharing' classes interact with Apex sharing records and whether a class running in system mode can read and insert Share object records.", answer: "Yes. A class running `without sharing` (or in system mode) can both read and insert Share object records. In fact, Apex managed sharing typically requires a class running without user-context restrictions to insert share records on behalf of users who may not themselves have sharing management permissions. The class uses `without sharing` to bypass the running user's record-level access, then manages Share object rows directly."),
                        StudyTopic(id: "record_access_obj7_q6", number: 101, question: "When programmatic sharing is the right choice over criteria-based sharing rules, given a dynamic sharing requirement that depends on complex related-object field values.", answer: "Use Apex managed sharing when:\n\n- Sharing must be determined by fields on related objects (criteria-based rules only evaluate fields on the record itself or its immediate parent).\n\n- Sharing logic involves complex multi-step business logic or external system lookups.\n\n- The access pattern changes frequently and cannot be expressed with static criteria.\n\n- You need sharing to persist through ownership changes (custom row cause)."),
                        StudyTopic(id: "record_access_obj7_q7", number: 102, question: "A trigger needs to share a newly created custom object record with a specific set of users based on business logic. What are the architectural steps using Apex managed sharing?", answer: ""),
                        StudyTopic(id: "record_access_obj7_q8", number: 103, question: "Create a custom sharing reason on the custom object.", answer: ""),
                        StudyTopic(id: "record_access_obj7_q9", number: 104, question: "Write an after-insert (and after-update) trigger on the custom object.", answer: ""),
                        StudyTopic(id: "record_access_obj7_q10", number: 105, question: "In the trigger handler (declared `without sharing`), evaluate the business logic to determine which users or groups should receive access.", answer: ""),
                        StudyTopic(id: "record_access_obj7_q11", number: 106, question: "Build a list of `MyObject__Share` records with the correct `ParentId`, `UserOrGroupId`, `AccessLevel`, and custom `RowCause`.", answer: ""),
                        StudyTopic(id: "record_access_obj7_q12", number: 107, question: "Insert the share records (use `Database.insert` with partial success handling).", answer: ""),
                        StudyTopic(id: "record_access_obj7_q13", number: 108, question: "For updates that revoke access, delete stale share records with the custom row cause before inserting new ones.", answer: ""),
                        StudyTopic(id: "record_access_obj7_q14", number: 109, question: "When a custom object's sharing table (e.g., MyObject\\_\\_Share) is queried to audit who has access and why, which fields indicate the sharing source and what the RowCause values mean.", answer: "Key fields:\n\n- `ParentId`: the record being shared.\n\n- `UserOrGroupId`: the recipient of access.\n\n- `AccessLevel`: Read or Edit.\n\n- `RowCause`: the source of the share record.\n\nCommon RowCause values:\n\n- `Owner`: the record owner.\n\n- `Manual`: manual share (sharing button or Apex without custom reason).\n\n- `Rule`: a sharing rule.\n\n- `ImplicitChild`/`ImplicitParent`: implicit hierarchy sharing.\n\n- Custom reasons (e.g., `MyCustomReason__c`): Apex-managed shares with a custom row cause.")
                    ]
                ),
                StudyObjective(
                    id: "record_access_obj8",
                    title: "Given a set of conditions, determine what sharing mechanism is appropriate to share records with External Users.",
                    topics: [
                        StudyTopic(id: "record_access_obj8_q1", number: 110, question: "How Experience Cloud (Community) user access to records is governed by OWD for external users and the difference between internal and external OWD settings.", answer: "External OWD is a separate, independently configured baseline for portal/community users. It can be equal to or more restrictive than the internal OWD. Community users cannot have a less restrictive external OWD than the internal OWD (the external setting cannot be more permissive). This allows orgs to lock down community users while maintaining open sharing internally."),
                        StudyTopic(id: "record_access_obj8_q2", number: 111, question: "How Customer Community versus Customer Community Plus licenses differ in role hierarchy support and the sharing mechanisms available to each.", answer: "| | Customer Community | Customer Community Plus |\n\n|---|---|---|\n\n| Role hierarchy | No | Yes (portal roles) |\n\n| Sharing rules | No | Yes |\n\n| Manual sharing | No | Yes |\n\n| Apex sharing | Yes | Yes |\n\n| Account-based implicit sharing | Yes | Yes |\n\nCustomer Community users have very limited sharing options. Customer Community Plus users have a role hierarchy and support sharing rules, enabling richer, more granular access control."),
                        StudyTopic(id: "record_access_obj8_q3", number: 112, question: "When Customer Community Plus is architecturally required versus Customer Community.", answer: "Customer Community Plus is required when:\n\n- Sharing rules are needed to grant record access to community users.\n\n- Role-based access among community users is necessary (e.g., managers and subordinates within an account).\n\n- Manual sharing by internal users to specific external users is needed.\n\nCustomer Community is sufficient for simpler B2C scenarios where account-level implicit sharing and Apex sharing meet all requirements."),
                        StudyTopic(id: "record_access_obj8_q4", number: 113, question: "Which portal/Experience Cloud license types support object-level sharing rules.", answer: "- Customer Community Plus: supports sharing rules.\n\n- Partner Community: supports sharing rules.\n\n- Customer Community: does NOT support sharing rules.\n\n- Guest User: does NOT support sharing rules in the same way (limited to specific guest-eligible criteria-based sharing rules)."),
                        StudyTopic(id: "record_access_obj8_q5", number: 114, question: "How account hierarchy-based implicit sharing works for portal users: a portal user gains access to records owned by users at their account and parent accounts in the hierarchy.", answer: "Portal users are associated with an Account. Salesforce implicitly shares records with portal users based on their account's position in the account hierarchy. A portal user on a child account gains access to records associated with parent accounts in the hierarchy. This implicit sharing applies to Accounts and their related Contacts and Cases owned by internal users associated with those accounts."),
                        StudyTopic(id: "record_access_obj8_q6", number: 115, question: "Given a partner portal scenario, which sharing mechanism grants portal users access to Account records they do not own without exposing internal records broadly?", answer: "Use Partner Community license + criteria-based sharing rules targeted at the portal user's role or public group. Alternatively, use Apex managed sharing to programmatically grant access to specific Accounts. Set external OWD to Private to ensure no unintended access, and use explicit sharing to open access only to the appropriate partner portal users."),
                        StudyTopic(id: "record_access_obj8_q7", number: 116, question: "How super user access for partner portal users works.", answer: "A Partner Community user with super user access can see all records shared with any user in the same account (partner account), not just their own. They effectively inherit the sharing of all portal users associated with their account. This is enabled on the contact record by checking \"Enable as Partner Super User.\""),
                        StudyTopic(id: "record_access_obj8_q8", number: 117, question: "When super user access should be used to grant broader record access within an account hierarchy.", answer: "Use super user access when a partner account manager or executive needs to see all records belonging to all users in their account (e.g., all Opportunities created by all sales reps in a partner account). Without super user, each partner user only sees their own records. Super user is appropriate for named \"account supervisors\" in partner scenarios, not for all partner users."),
                        StudyTopic(id: "record_access_obj8_q9", number: 118, question: "A customer community user should see only their own Cases and Cases shared explicitly by a support agent. Which combination of OWD and sharing mechanism achieves this?", answer: ""),
                        StudyTopic(id: "record_access_obj8_q10", number: 119, question: "Set **external OWD for Case to Private** (each user sees only their own Cases).", answer: ""),
                        StudyTopic(id: "record_access_obj8_q11", number: 120, question: "Support agents use **manual sharing** (or Apex sharing) to explicitly share specific Cases with the customer community user.", answer: ""),
                        StudyTopic(id: "record_access_obj8_q12", number: 121, question: "Customer Community license supports Apex sharing, so for high-volume or automated explicit sharing, use Apex managed sharing with a custom row cause.", answer: ""),
                        StudyTopic(id: "record_access_obj8_q13", number: 122, question: "Guest user record access limitations (no role, no manual sharing).", answer: "Guest users have no role, no profile-based hierarchy position, and cannot be directly targeted by manual shares. They have very limited access: only records explicitly made visible via specific sharing mechanisms. Guest users also cannot own records."),
                        StudyTopic(id: "record_access_obj8_q14", number: 123, question: "Restrictions on the types of sharing rules that apply to guest users.", answer: "Guest users can only be targeted by criteria-based sharing rules where the target is set to \"Guest User.\" Ownership-based sharing rules cannot target guest users. The number and type of objects available for guest user sharing rules are also restricted. Salesforce has progressively tightened guest user sharing across releases."),
                        StudyTopic(id: "record_access_obj8_q15", number: 124, question: "How to compensate for guest user limitations using groups and criteria-based sharing rules for unauthenticated users.", answer: "Create a public group that includes the Guest User for the site. Then create a criteria-based sharing rule on the target object where the criteria match records that should be public, sharing them with that public group at Read Only. This is the only declarative mechanism to make records visible to unauthenticated (guest) users.")
                    ]
                ),
                StudyObjective(
                    id: "record_access_obj9",
                    title: "Given a set of conditions, determine how record access overrides support the record access requirements.",
                    topics: [
                        StudyTopic(id: "record_access_obj9_q1", number: 125, question: "How manual sharing allows record owners and administrators to grant one-time access and the limitations of manual shares when ownership changes.", answer: "Record owners (and admins) can use the \"Sharing\" button on a record to manually grant specific users or groups Read or Read/Write access. Manual shares with `RowCause = Manual` are deleted automatically when the record's ownership changes. This makes manual sharing unsuitable for persistent access requirements that must survive ownership transfers."),
                        StudyTopic(id: "record_access_obj9_q2", number: 126, question: "When is manual sharing the appropriate override mechanism versus a permanent sharing rule, given a one-time cross-team collaboration requirement?", answer: "Use manual sharing for:\n\n- One-time or short-term collaboration.\n\n- A single specific record, not a category of records.\n\n- When no pattern exists that could be expressed as a sharing rule.\n\nUse a sharing rule for:\n\n- Recurring, pattern-based access.\n\n- Access that must apply to all records meeting certain criteria.\n\n- Scenarios where the sharing audience changes (group membership changes propagate automatically)."),
                        StudyTopic(id: "record_access_obj9_q3", number: 127, question: "How 'View All' and 'Modify All' object permissions override all record-level sharing mechanisms, including OWD, sharing rules, and manual shares.", answer: "View All (object permission) and Modify All (object permission) grant the user access to every record of that object, bypassing OWD, sharing rules, role hierarchy, manual shares, and Apex shares entirely. They are object-scoped overrides. The system-level equivalents (View All Data / Modify All Data) do this across every object in the org."),
                        StudyTopic(id: "record_access_obj9_q4", number: 128, question: "System Administrator profile access: why admins can see all records regardless of OWD and sharing rules, and how to model a scenario where even admins should be restricted.", answer: "The System Administrator profile has View All Data and Modify All Data enabled by default, which overrides all sharing. To restrict even admins: create a custom admin profile without View All Data / Modify All Data. Then control access using standard sharing mechanisms. Note: any user who can manage profiles or permission sets could re-grant themselves access, so true admin restriction requires very careful permission management and audit trails."),
                        StudyTopic(id: "record_access_obj9_q5", number: 129, question: "How to use the 'Why can I see this record?' (Sharing Hierarchy / Record Access) tool in Salesforce to diagnose unexpected record visibility.", answer: "Navigate to the record and click Sharing (or \"Why can I see this record?\" in some contexts). This shows a summary of all sharing sources granting access: the owner, sharing rules, hierarchy, teams, manual shares, and Apex shares. It also shows the access level granted by each source. Use this for real-time, record-specific access diagnosis without SOQL."),
                        StudyTopic(id: "record_access_obj9_q6", number: 130, question: "How the Sharing Debugger (Setup > Sharing Settings > Debug) works and what information it surfaces about a user's access to a specific record.", answer: "The Sharing Debugger allows admins to enter a username and a record ID to see a full breakdown of how that user gets (or doesn't get) access to that specific record. It evaluates all sharing sources and shows which rows in the Share object are granting access and why. It is the primary admin tool for complex sharing investigation without requiring SOQL."),
                        StudyTopic(id: "record_access_obj9_q7", number: 131, question: "Given a scenario where a user unexpectedly has access to a record, which combination of sharing sources (OWD, hierarchy, sharing rules, manual share, Apex share) could explain it?", answer: "Check these sources in order:"),
                        StudyTopic(id: "record_access_obj9_q8", number: 132, question: "**OWD**: is it Public Read Only or Public Read/Write? If so, everyone has access by default.", answer: ""),
                        StudyTopic(id: "record_access_obj9_q9", number: 133, question: "**Role hierarchy**: is the user above the owner in the hierarchy with \"Grant Access Using Hierarchies\" enabled?", answer: ""),
                        StudyTopic(id: "record_access_obj9_q10", number: 134, question: "**Sharing rules**: does any rule match the record's criteria or owner and include the user's role or group?", answer: ""),
                        StudyTopic(id: "record_access_obj9_q11", number: 135, question: "**Manual share**: was a manual share created for this user on this record?", answer: ""),
                        StudyTopic(id: "record_access_obj9_q12", number: 136, question: "**Apex share**: is there a row in the Share object with a custom RowCause for this user?", answer: ""),
                        StudyTopic(id: "record_access_obj9_q13", number: 137, question: "**View All / Modify All**: does the user have object-level or system-level override permissions?", answer: ""),
                        StudyTopic(id: "record_access_obj9_q14", number: 138, question: "When using High Volume Customer Portal (HVCP) users, which standard sharing mechanisms are unavailable and what must replace them?", answer: "HVCP users have no role, no position in the role hierarchy, and cannot be targeted by sharing rules or manual shares. Available mechanisms:\n\n- Account-based implicit sharing (Contacts and Cases on their account).\n\n- Apex managed sharing (only programmatic option for non-implicit access).\n\n- OWD for external users (sets the baseline).\n\nFor any complex sharing requirement with HVCP users, Apex managed sharing is the required solution.")
                    ]
                )
            ]
        ),

        // Access to Other Data (1 objectives, 22 topics)
        StudySection(
            id: "other_data_access",
            title: "Access to Other Data",
            color: Color(red: 0.55, green: 0.35, blue: 0.75),
            lightColor: Color(red: 0.94, green: 0.90, blue: 0.98),
            icon: "folder.fill",
            objectives: [
                StudyObjective(
                    id: "other_data_access_obj1",
                    title: "Given a scenario, determine the appropriate access control needed to grant access to data that is not standard or custom objects.",
                    topics: [
                        StudyTopic(id: "other_data_access_obj1_q1", number: 139, question: "How Reports and Dashboards folder sharing works and what access level is required to view, edit, or manage folders.", answer: "Reports and Dashboards are stored in folders. Access is controlled at the folder level:\n\n- Viewer: can run reports/dashboards in the folder, cannot edit.\n\n- Editor: can run and modify reports/dashboards, cannot manage folder settings.\n\n- Manager: full control including sharing the folder with others and changing membership.\n\nFolder access is independent of record-level sharing. A user can have folder access but still only see records their sharing model allows when running a report."),
                        StudyTopic(id: "other_data_access_obj1_q2", number: 140, question: "How the 'running user' setting on a dashboard controls which records appear in charts and metrics.", answer: "The dashboard's running user determines whose data context is used to execute the underlying reports. If the running user is set to a specific person, all dashboard viewers see data as that person would see it (based on that person's record access). If set to \"Logged-in User,\" each viewer sees their own data."),
                        StudyTopic(id: "other_data_access_obj1_q3", number: 141, question: "An executive team needs a dashboard showing data from Opportunities with Private OWD, but the dashboard should always reflect all records regardless of the viewer's data access. Which configuration achieves this?", answer: "Set the running user to a user with View All Data or View All on Opportunities (e.g., a dedicated integration/admin user). All viewers of the dashboard see data through that user's lens, which includes all Opportunity records. Viewers do not need their own access to those records to see the aggregated dashboard data."),
                        StudyTopic(id: "other_data_access_obj1_q4", number: 142, question: "Security implications of setting the dashboard running user to an admin with View All Data.", answer: "All viewers of the dashboard effectively see data the admin can see, regardless of the viewers' own record access. This can expose sensitive record data in aggregate or individual chart drill-downs. If viewers can drill into the dashboard, they may navigate to records they would not otherwise have access to. Set sharing on the dashboard folder carefully and consider whether drill-through access is enabled."),
                        StudyTopic(id: "other_data_access_obj1_q5", number: 143, question: "How report folder sharing interacts with org-wide sharing — specifically, whether a user with access to a report folder can run reports that return records beyond their own record-level sharing access.", answer: "No. Report folder access controls whether a user can see and run the report, but when the report runs, it returns only records the running user has access to (which defaults to the logged-in user). Folder access does not bypass OWD or sharing. The exception is when a fixed running user with broader access is configured on a dashboard."),
                        StudyTopic(id: "other_data_access_obj1_q6", number: 144, question: "How to control access to Salesforce Files (ContentDocument, ContentVersion) using sharing rules and which OWD settings govern file visibility.", answer: "Files follow the sharing of the record they are attached to. The ContentDocument object has its own OWD setting. Sharing rules can be applied to ContentDocument. Additionally, files can be shared with individuals, groups, or via library membership. The OWD for Files (ContentDocument) in Setup governs baseline visibility, and it can be set to Private, Viewer, Collaborator, or Controlled by Parent."),
                        StudyTopic(id: "other_data_access_obj1_q7", number: 145, question: "How Content Library permissions (Viewer, Author, Administrator) differ from record-level file sharing.", answer: "- Viewer: can view and download files in the library.\n\n- Author: can add, edit, and delete files they added to the library.\n\n- Administrator: full control of library content and membership.\n\nLibrary permissions are set at the library level, not the individual file level. Record-linked file sharing (attaching to a record) is separate; users with record access can see attached files subject to the file's OWD."),
                        StudyTopic(id: "other_data_access_obj1_q8", number: 146, question: "When library-based access is appropriate over record-linked sharing for Salesforce Files.", answer: "Use libraries when:\n\n- Files must be centrally managed and accessed independent of specific records.\n\n- A curated content set (product docs, templates, knowledge base) needs controlled access by a defined audience.\n\n- Version control at the library level is needed.\n\nUse record-linked sharing when files are specific to a transaction or record (an attachment to a Case or Opportunity) and access should follow the record's sharing model."),
                        StudyTopic(id: "other_data_access_obj1_q9", number: 147, question: "A team needs access to a Salesforce File attached to an Opportunity but does not have access to the Opportunity itself. Which mechanism grants access to the file without opening up Opportunity access?", answer: "Share the ContentDocument record directly with the team (via a sharing rule on ContentDocument, or by adding the file to a Content Library the team has access to). Alternatively, use Apex to insert a `ContentDocumentLink` record with the relevant user or group. This grants file access without modifying Opportunity OWD or sharing rules."),
                        StudyTopic(id: "other_data_access_obj1_q10", number: 148, question: "The three Territory Management model states (Planning, Active, Archived) and which state allows sharing to be generated.", answer: "- Planning: build and test territory rules, no sharing generated.\n\n- Active: sharing is generated; territory assignments drive record access.\n\n- Archived: territory model deactivated; sharing from this model is removed.\n\nOnly the Active state generates sharing records that affect record visibility."),
                        StudyTopic(id: "other_data_access_obj1_q11", number: 149, question: "How territory rules and manual assignments are applied to assign records to territories.", answer: "Territory rules are filter criteria applied to object records (e.g., Account Billing State = CA) to automatically assign records to territories. Manual assignments allow admins or authorized users to directly assign individual records to territories outside of rule logic. Both types of assignments create sharing records that grant territory members access to those records."),
                        StudyTopic(id: "other_data_access_obj1_q12", number: 150, question: "How Territory Management record access differs from role hierarchy-based access, and what access paths a record gets when assigned to a territory.", answer: "Role hierarchy grants access upward (manager sees subordinate's records). Territory Management grants access horizontally (all members of a territory see all records assigned to that territory, regardless of ownership or hierarchy position). A record assigned to a territory creates sharing rows for all territory members, providing a parallel access path independent of the role hierarchy."),
                        StudyTopic(id: "other_data_access_obj1_q13", number: 151, question: "How territory sharing stacks with role hierarchy and OWD-based sharing — specifically, how a user in a territory that includes an Account gets access to that Account even if they are not the owner and the role hierarchy does not include the owner.", answer: "Territory sharing is additive on top of OWD and role hierarchy sharing. A user who is a member of a territory that an Account is assigned to gets Read (or Read/Write, per territory settings) access to that Account via a territory-generated sharing record. This is independent of ownership and hierarchy. The user does not need any relationship to the Account owner to gain this access."),
                        StudyTopic(id: "other_data_access_obj1_q14", number: 152, question: "How access to Chatter posts, groups, and feeds is governed — specifically when a private Chatter group prevents non-members from seeing feed items on records they otherwise have access to.", answer: "Chatter groups have Public, Private, and Unlisted types. Feed items posted to a Private Chatter group are visible only to group members, even if non-members have record access to the record the post is attached to. Record-level sharing does not override Chatter group privacy. Non-members cannot see feed updates that were posted within the private group context."),
                        StudyTopic(id: "other_data_access_obj1_q15", number: 153, question: "How Knowledge article visibility is controlled through data categories, user profiles, and article types in Experience Cloud and internal portals.", answer: "Knowledge article visibility is controlled by:\n\n- Data categories: articles are assigned to categories; user profiles are mapped to category visibility groups, controlling which categories (and therefore articles) each user can see.\n\n- Article type / record type: profiles control which record types users can access, limiting which article types are visible.\n\n- Channel: articles are published to specific channels (Internal, Partner, Customer, Public). Users only see articles published to channels their license supports."),
                        StudyTopic(id: "other_data_access_obj1_q16", number: 154, question: "How List Views can be restricted or shared using visibility settings and when this becomes a security concern if the underlying OWD is Private.", answer: "List Views have three visibility options: Only I can see it (private), All users can see it, and Share with groups of users. Sharing a List View does not grant record access. However, if OWD is Private, a shared list view may return zero records for most users (they see only their own records). Conversely, if OWD is more open, a shared list view could expose more data than intended. The security concern: list view filters may not be restrictive enough, and users with broader OWD access see all records matching the filter."),
                        StudyTopic(id: "other_data_access_obj1_q17", number: 155, question: "A compliance officer needs to see all email messages logged against Contacts in a Private OWD org. Which access controls apply to Email Message records and how should access be granted?", answer: "Email Message records have their own OWD (can be set to Private or Public Read Only). To grant a compliance officer access to all Email Message records:"),
                        StudyTopic(id: "other_data_access_obj1_q18", number: 156, question: "Set Email Message OWD to **Private** (most secure baseline).", answer: ""),
                        StudyTopic(id: "other_data_access_obj1_q19", number: 157, question: "Grant the compliance officer **View All** on the Email Message object via a permission set, or use a sharing rule to share Email Messages with their role.", answer: ""),
                        StudyTopic(id: "other_data_access_obj1_q20", number: 158, question: "Alternatively, use **View All Data** (system permission) if the officer needs global access, but this is overly broad.", answer: "The most targeted solution is View All on the Email Message object via a permission set."),
                        StudyTopic(id: "other_data_access_obj1_q21", number: 159, question: "How access to Price Books, Products, and Assets is controlled and whether they follow the same record-level sharing model as custom objects.", answer: "- Price Books: access is controlled via the Price Book's \"Archive\" status and profile settings. Active Price Books are visible to all users with the \"Use Price Books\" permission. OWD-style sharing does not apply.\n\n- Products: Product2 records are accessible to any user with Read on the Product object. Standard record-level sharing does not apply.\n\n- Assets: follow standard OWD and sharing model (with an OWD that can be set in Setup). They behave more like custom objects in terms of record-level access.\n\nPrice Books and Products are not governed by OWD or sharing rules; Assets are."),
                        StudyTopic(id: "other_data_access_obj1_q22", number: 160, question: "Which mechanisms control access to external data objects (External Objects via Salesforce Connect) and how their sharing model differs from standard Salesforce objects.", answer: "External Objects follow a simplified sharing model:\n\n- They support OWD (Private, Public Read Only, Public Read/Write) configured in Setup.\n\n- They support manual sharing and some sharing rules depending on the adapter and configuration.\n\n- They do NOT have a Share object (no `ExternalObject__Share` table) and do not support Apex managed sharing.\n\n- Access is also governed by the External Data Source's authentication (named credentials, per-user or org-wide auth). A user may have object-level access but be blocked by the external system's own auth requirements.\n\nThe primary difference: no programmatic sharing table and no Apex sharing support.")
                    ]
                )
            ]
        ),

        // Implications of Security Model Choice (3 objectives, 26 topics)
        StudySection(
            id: "security_implications",
            title: "Implications of Security Model Choice",
            color: Color(red: 0.80, green: 0.40, blue: 0.20),
            lightColor: Color(red: 1.00, green: 0.94, blue: 0.88),
            icon: "exclamationmark.triangle.fill",
            objectives: [
                StudyObjective(
                    id: "security_implications_obj1",
                    title: "Given a scenario, determine the scalability implications of the sharing solution.",
                    topics: [
                        StudyTopic(id: "security_implications_obj1_q1", number: 161, question: "Sharing recalculation behavior when OWD is changed — which operations trigger a recalculation, how long it can take, and the risk of record access being temporarily inconsistent.", answer: "Changing OWD triggers a full sharing recalculation for the affected object. This is a background process that rebuilds all sharing rows in the Share object. For orgs with millions of records and complex sharing rules, this can take hours. During recalculation, access may be temporarily inconsistent: some records may show stale access states. Plan OWD changes during off-peak hours and use the Defer Sharing Calculation feature during migrations."),
                        StudyTopic(id: "security_implications_obj1_q2", number: 162, question: "Why deeply nested public groups or very large role hierarchies cause sharing recalculation timeouts.", answer: "Salesforce must resolve group membership recursively during recalculation. A deeply nested group (Group A contains Group B contains Group C, etc.) exponentially increases resolution time. Very large role hierarchies with thousands of roles produce an enormous number of sharing row combinations. When resolution exceeds platform time limits, the recalculation job times out, leaving sharing in a partially updated state."),
                        StudyTopic(id: "security_implications_obj1_q3", number: 163, question: "How a large number of criteria-based sharing rules on a high-volume object creates recalculation performance risks and lock contention during bulk record updates.", answer: "Each criteria-based sharing rule must be evaluated whenever a relevant field changes on a record. With many rules on a high-volume object (millions of records, frequent updates), the system must recalculate sharing for every updated record against every rule. This creates:\n\n- Lock contention: multiple transactions trying to update Share object rows simultaneously.\n\n- DML timeouts: sharing recalculation DML hitting governor limits.\n\n- Async queue backlog: sharing jobs queuing up faster than they can process."),
                        StudyTopic(id: "security_implications_obj1_q4", number: 164, question: "Architectural patterns to mitigate sharing recalculation timeouts from deeply nested groups or large role hierarchies.", answer: "- Flatten group structures: reduce nesting depth to 2-3 levels maximum.\n\n- Simplify role hierarchy: use fewer roles, combine where possible.\n\n- Use criteria-based rules judiciously: fewer rules on high-volume objects.\n\n- Use Defer Sharing Calculation: during bulk data loads or migrations.\n\n- Batch Apex sharing: spread sharing updates across async jobs instead of synchronous triggers.\n\n- Consolidate sharing rules: use public groups and OR-logic in criteria to reduce total rule count."),
                        StudyTopic(id: "security_implications_obj1_q5", number: 165, question: "Performance trade-offs between using 'Public Read/Write' OWD (no recalculation, broader access) versus 'Private' OWD with sharing rules in a rapidly growing org.", answer: "- Public Read/Write: no sharing rows created, no recalculation overhead, maximum performance. But all users see all records, eliminating data segmentation.\n\n- Private + sharing rules: generates millions of sharing rows as the org grows, recalculation complexity scales with record volume and rule count. More secure but performance-intensive.\n\nThe trade-off is security versus scalability. For very large orgs with strict access requirements, architect the sharing model carefully upfront. Once Private OWD is in use at scale, switching back to Public Read/Write also requires full recalculation."),
                        StudyTopic(id: "security_implications_obj1_q6", number: 166, question: "How the 'Defer Sharing Calculation' feature works, when it should be used during data migration, and the risk of accessing records before recalculation completes.", answer: "Defer Sharing Calculation pauses sharing recalculation jobs. New sharing rules, OWD changes, or bulk record updates do not trigger immediate recalculation while deferred. Use it during large data migrations to prevent performance degradation. After the migration, resume recalculation to rebuild all sharing rows.\n\nRisk: while deferred, users may not have correct access to newly loaded records. Never run production business operations while sharing is deferred."),
                        StudyTopic(id: "security_implications_obj1_q7", number: 167, question: "When to prefer async processing for Apex managed sharing versus synchronous trigger-based sharing.", answer: "Prefer async processing (Queueable, Batchable, Platform Events) when:\n\n- The number of records being shared is large (hundreds or thousands per transaction).\n\n- Share object DML in a synchronous trigger would risk hitting governor limits.\n\n- Sharing does not need to be applied before the transaction completes (eventual consistency is acceptable).\n\nUse synchronous trigger-based sharing only when sharing must be in place before the transaction completes and record volume is low."),
                        StudyTopic(id: "security_implications_obj1_q8", number: 168, question: "How Apex managed sharing at high volume (triggered on every record insert) can degrade performance compared to declarative sharing rules.", answer: "Apex managed sharing inserts Share object records via DML in code, subject to governor limits (10,000 DML rows per transaction). At high volume, every insert trigger fires Apex that performs additional DML for share records. This can cause:\n\n- Governor limit violations (DML limit exceeded).\n\n- Lock contention on the Share object table.\n\n- Trigger recursion if not carefully guarded.\n\nDeclarative sharing rules are processed by the platform's optimized sharing engine, which is more efficient than Apex DML at scale."),
                        StudyTopic(id: "security_implications_obj1_q9", number: 169, question: "An org processes millions of records and needs complex cross-team sharing. Which sharing approach (declarative vs. programmatic) is most scalable and why?", answer: "Declarative sharing rules are generally more scalable for high-volume orgs because the platform's sharing engine is optimized for bulk processing and handles recalculation natively. However, if the sharing logic is too complex for declarative rules (e.g., depends on related object fields), use Apex managed sharing with async processing (Batchable/Queueable), which spreads DML load across multiple transactions. Avoid synchronous trigger-based Apex sharing at high volume.")
                    ]
                ),
                StudyObjective(
                    id: "security_implications_obj2",
                    title: "Given a set of conditions, determine the license limitations that will impact the intended sharing solution.",
                    topics: [
                        StudyTopic(id: "security_implications_obj2_q1", number: 170, question: "Which Salesforce license types do not support role hierarchy-based record sharing and how that affects sharing architecture for external users.", answer: "- Customer Community (standard): no role hierarchy for external users. Sharing architecture must rely on account-based implicit sharing, Apex managed sharing, and OWD.\n\n- High Volume Customer Portal (HVCP): no role hierarchy, no sharing rules, no manual sharing. Apex sharing and account-based implicit sharing only.\n\n- Guest User: no role, no hierarchy, no manual sharing. Criteria-based sharing rules via guest-eligible public groups only.\n\nWithout role hierarchy, all hierarchy-based access patterns must be replaced with explicit sharing mechanisms."),
                        StudyTopic(id: "security_implications_obj2_q2", number: 171, question: "High Volume Customer Portal (HVCP) license limitations: which sharing mechanisms are unavailable (no role, no sharing rules) and which alternatives (Apex sharing, account hierarchy) must be used.", answer: "HVCP users lack:\n\n- Role in the hierarchy (no hierarchy-based access).\n\n- Eligibility for sharing rules.\n\n- Manual sharing.\n\nAvailable mechanisms:\n\n- Account-based implicit sharing: Cases and Contacts on their Account.\n\n- Apex managed sharing: only way to share arbitrary records explicitly.\n\n- OWD for external users: sets the visibility floor.\n\nFor any record outside implicit sharing scope, Apex is the only option."),
                        StudyTopic(id: "security_implications_obj2_q3", number: 172, question: "Guest user license restrictions on record access: why guest users cannot be members of public groups or receive manual shares, and the compliant workaround.", answer: "Guest users have no identity-based membership in groups (they are unauthenticated). They cannot be explicitly targeted by manual sharing because there is no persistent user identity. The workaround: create a public group specifically for the site's Guest User, use criteria-based sharing rules targeting that group to make specific records visible (Read Only). This is the only compliant declarative mechanism."),
                        StudyTopic(id: "security_implications_obj2_q4", number: 173, question: "A company wants to grant Partner Community users access to custom object records using criteria-based sharing rules. Which license type supports this and what are the restrictions?", answer: "Partner Community licenses support criteria-based sharing rules for custom objects. Restrictions:\n\n- The partner user must have object-level Read permission on the object.\n\n- The sharing rule must target a role or group that includes the partner users.\n\n- External OWD for the object must be Private or Public Read Only (not Public Read/Write, which would already grant access).\n\n- Not all objects support sharing rules for external users; check Salesforce documentation for supported objects."),
                        StudyTopic(id: "security_implications_obj2_q5", number: 174, question: "How Salesforce Platform license differs from full Salesforce license in terms of object accessibility and whether sharing rules for standard objects can apply to Platform license users.", answer: "The Salesforce Platform license provides access to custom apps and a limited set of standard objects (Accounts, Contacts, custom objects, and a few others). Standard objects like Opportunities, Leads, Cases, and Campaigns are not accessible. Sharing rules for those excluded standard objects cannot apply to Platform license users because the users have no access to those objects regardless of sharing. Architects must check license object entitlements before designing sharing for Platform license user populations."),
                        StudyTopic(id: "security_implications_obj2_q6", number: 175, question: "How the number of permission sets or permission set group assignments available differs by license type, and when this constraint affects the architect's ability to layer granular permissions.", answer: "Different license types have different limits on the number of permission sets that can be assigned (typically 1,000 for full licenses but fewer for external/community licenses). More practically, the available permissions within permission sets are constrained by license type: a Customer Community license user cannot be granted permissions that the license does not support, regardless of what the permission set contains. When designing granular permission layering for external users, validate each permission against what the license type allows.")
                    ]
                ),
                StudyObjective(
                    id: "security_implications_obj3",
                    title: "Given a set of conditions, determine how to test the sharing model.",
                    topics: [
                        StudyTopic(id: "security_implications_obj3_q1", number: 176, question: "How to use the 'Login As' feature and 'Record Access' page to validate record visibility for a specific user without modifying the sharing model.", answer: "Use Setup > Users > Login (or the \"Login\" button on the user record) to log in as that user. Navigate to the record in question and confirm visibility, edit ability, and field visibility. Alternatively, on the record detail page, click Sharing to view the sharing hierarchy and which sources grant access. This is non-destructive testing that does not modify sharing configuration."),
                        StudyTopic(id: "security_implications_obj3_q2", number: 177, question: "How to query the Share object (e.g., AccountShare) directly in a sandbox to enumerate all sharing entries for a record and identify which sources contributed access to a given user.", answer: "Run SOQL in the Developer Console or Workbench:\n\n```soql\n\nSELECT ParentId, UserOrGroupId, AccessLevel, RowCause\n\nFROM AccountShare\n\nWHERE ParentId = '[RecordId]'\n\n```\n\nReview `RowCause` values to determine each sharing source (Owner, Manual, Rule, Apex custom reason, hierarchy). Cross-reference `UserOrGroupId` with the target user's group memberships to confirm which rows grant them access."),
                        StudyTopic(id: "security_implications_obj3_q3", number: 178, question: "How to write SOQL queries and Apex tests that validate sharing rules are correctly applied in a test context using Test.startTest() and runAs().", answer: "```apex\n\n@IsTest\n\nstatic void testSharingRuleApplied() {\n\nUser targetUser = [SELECT Id FROM User WHERE Username = 'testuser@example.com'];\n\nAccount acc = new Account(Name = 'Test', BillingState = 'CA');\n\ninsert acc;\n\nTest.startTest();\n\nSystem.runAs(targetUser) {\n\nList<Account> visible = [SELECT Id FROM Account WHERE Id = :acc.Id];\n\nSystem.assertEquals(1, visible.size(), 'User should see the Account');\n\n}\n\nTest.stopTest();\n\n}\n\n```\n\n`System.runAs()` enforces the user's sharing context for SOQL inside the block. Use this pattern to assert whether a user can or cannot see specific records."),
                        StudyTopic(id: "security_implications_obj3_q4", number: 179, question: "How Apex unit tests behave with respect to sharing when using System.runAs(): which sharing rules are evaluated, whether sharing table data carries over from test setup, and why test isolation can produce false positives.", answer: "- `System.runAs()` evaluates sharing rules and role hierarchy for the specified user.\n\n- Test data created in `@TestSetup` or within the test method is visible within the test transaction.\n\n- Sharing rules ARE evaluated in test context, but only for test data created within that transaction.\n\n- False positives risk: if the test creates data as an admin and then runs as the target user, the admin-created data may not have sharing rows populated yet (async recalculation). Tests should create data in the `runAs` block or use the `runAs` user as the data owner to ensure correct sharing row generation."),
                        StudyTopic(id: "security_implications_obj3_q5", number: 180, question: "A QA team needs to validate that a criteria-based sharing rule fires correctly when a specific field changes. What test strategy and tooling should an architect recommend?", answer: ""),
                        StudyTopic(id: "security_implications_obj3_q6", number: 181, question: "**Apex test with `System.runAs()`**: create a record with a field value that does NOT match the criteria, confirm the target user cannot see it. Update the field to match criteria, confirm the user can see it.", answer: ""),
                        StudyTopic(id: "security_implications_obj3_q7", number: 182, question: "**Developer Console / Workbench SOQL**: query the Share object before and after the field change to confirm new sharing rows are created.", answer: ""),
